export const topicsByLanguage: Record<TopicLanguage, Topic[]> = {
  en: topics,
  fr: topics.map((topic) => {
    const translation = frenchTopicContent[topic.slug];
    return translation ? { ...topic, ...translation } : topic;
  }),
};

export function getTopics(language: TopicLanguage = 'en') {
  return topicsByLanguage[language];
}
